var KB=8.617333e-5; // eV/K
function factor(E, T){ return Math.exp(-E/(KB*T)); }
function populationRatio(E1, E2, T){ return Math.exp(-(E2-E1)/(KB*T)); } // N2/N1
var EXPORTS={KB:KB, factor:factor, populationRatio:populationRatio};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.BoltzmannForgePure = EXPORTS; }
